import { t, getLanguage, setLanguage, localDate, localNumber, programmeLabel, PROGRAMMES } from './i18n.js?v=4.8.0';
import { createStudentJourney } from './student-journey.js?v=4.8.2';
import {
  auth, RoomAccessMode, signInWithGoogle, signOutUser, subscribeAuth, ensureProfile, getRoles,
  subscribeTeacherWorkspace, createStudent, createBatch, createBatchRoom, terminateStudentRoom, ensureBatchRoom,
  lookupRoom, createGuardianRequest, approveGuardianRequest, rejectGuardianRequest,
  guardianApprovals, guardianBatchAccess, guardianStudentReport, guardianBatchReport, requestGuardianChildLink, createOrUpdatePresence,
  listCurriculumVersions, saveCurriculumVersion, listCurriculumBooks, listCurriculumChapters, saveCurriculumBook, saveCurriculumChapter, setCurriculumVersionStatus, listAssessmentTemplates, saveAssessmentTemplate, exportTeacherData, recordBatchSession, listBatchSessions, subscribeConnectionState,
  guardianNotifications, markGuardianNotificationRead, setAccountBlocked, setAdministratorRole, listAdminAccounts, listAdminAudit, createTeacherTask, updateTeacherTask,
} from './demo-service.js?v=4.8.3';

const $ = (s, r = document) => r.querySelector(s);
const $$ = (s, r = document) => [...r.querySelectorAll(s)];
const root = $('#viewRoot');
const modal = $('#appModal');
const state = { user:null, profile:null, roles:{isAdmin:false,isSuperAdmin:false}, language:getLanguage(), intent:'teacher', view:'dashboard', students:[], batches:[], requests:[], activities:[], guardianNotifications:[], adminAccounts:[], adminAudit:[], tasks:[], stop:null, stopConnection:null, authTimer:null, selectedStudent:null, selectedBatch:null, guardianRoom:null, guardianState:null, curriculum:[] };
const esc = value => String(value ?? '').replace(/[&<>'"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const time = value => value?.toDate ? value.toDate().getTime() : (new Date(value || 0).getTime() || 0);
const recent = (items, key='createdAt') => [...items].sort((a,b) => time(b[key]) - time(a[key]));
const txt = key => t(key, state.language);
const num = value => localNumber(value, state.language);
const date = value => localDate(value, state.language, {day:'numeric',month:'short'});
const initials = name => String(name || '').trim().split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase() || 'শি';

function toast(message, type='success') { const item=document.createElement('div'); item.className=`toast ${type}`; item.textContent=message; $('#toastRegion').append(item); setTimeout(()=>item.remove(),4500); }
function err(error) { console.error(error); const code=String(error?.code||''); if(code.includes('permission')) toast(state.language==='bn'?'এই কাজের অনুমতি নেই। সাইন-ইন বা নিরাপত্তা নিয়ম পরীক্ষা করুন।':'You do not have permission for this action.','error'); else if(code.includes('popup')) toast(state.language==='bn'?'Google সাইন-ইন উইন্ডো বন্ধ হয়েছে বা বাধা পেয়েছে।':'Google sign-in was closed or blocked.','error'); else toast(error?.message || txt('failed'),'error'); }
function show(name) { ['loadingScreen','signInScreen','guardianScreen','teacherShell'].forEach(id=>$('#'+id).classList.toggle('hidden',id!==name)); }
function setView(view) { if(view==='library'&&!state.roles.isAdmin)view='dashboard'; if(view==='admin'&&!state.roles.isAdmin)view='dashboard'; state.view=view; state.selectedStudent=null; state.selectedBatch=null; $$('.nav-link,.mobile-nav-link').forEach(button=>button.classList.toggle('active',button.dataset.view===view)); $('#viewTitle').textContent=viewName(view); $('#topKicker').textContent=view==='dashboard'?(state.language==='bn'?'শিক্ষক ড্যাশবোর্ড':'TEACHER WORKSPACE'):(state.language==='bn'?'শিক্ষক কর্মক্ষেত্র':'TEACHER WORKSPACE'); $('#sidebar').classList.remove('open'); render(); }
function viewName(view){ return {dashboard:txt('dashboard'),students:txt('students'),batches:txt('batches'),plans:txt('calendar'),requests:txt('requests'),library:txt('library'),admin:txt('admin')}[view]||txt('dashboard'); }
function syncLanguage(){ document.documentElement.lang=state.language==='bn'?'bn':'en'; document.body.classList.toggle('lang-en',state.language==='en'); updateSyncStatus({online:typeof navigator==='undefined'||navigator.onLine}); document.title=state.language==='bn'?'শিক্ষার্থীর অগ্রগতি':'Student Progress'; $('[data-copy="appName"]')?.replaceChildren(document.createTextNode(txt('appName'))); $('#authBrandName').textContent=txt('appName'); $('#signInTitle').textContent=txt('signInTitle'); $('#signInText').textContent=txt('signInText'); $$('[data-copy]').forEach(el=>el.textContent=txt(el.dataset.copy)); $$('.language-choice').forEach(el=>el.classList.toggle('active',el.dataset.language===state.language)); $('#languageBtn').textContent=state.language==='bn'?'EN':'বাং'; if(state.user && state.intent==='teacher') render(); if(state.user && state.intent==='guardian') renderGuardian(); }
function setLang(language){state.language=language==='en'?'en':'bn';setLanguage(state.language);syncLanguage();}
function cleanUnsubscribe(){try{state.stop?.();}catch(_){ }state.stop=null;try{state.stopConnection?.();}catch(_){ }state.stopConnection=null;}
function updateSyncStatus(connection){const target=$('#syncStatus');if(!target)return;const offline=!connection?.online;target.classList.toggle('is-offline',offline);target.classList.toggle('is-online',!offline);target.textContent=offline?(state.language==='bn'?'অফলাইন · ব্যাকআপের অপেক্ষায়':'Offline · waiting to back up'):(state.language==='bn'?'ব্যাকআপ প্রস্তুত':'Backed up');}
	function updateGuardianNotificationBadge(){const badge=$('#guardianNoticeBadge');const button=$('#guardianNoticeBtn');if(!badge||!button)return;const unread=state.guardianNotifications.filter(item=>!item.readAt).length;badge.textContent=unread>99?'99+':String(unread);badge.classList.toggle('hidden',!unread);button.setAttribute('aria-label',txt('notifications'));}
	async function refreshGuardianNotifications(){if(!state.user||state.intent!=='guardian')return;try{state.guardianNotifications=recent(await guardianNotifications(state.user.uid));updateGuardianNotificationBadge();}catch(error){console.warn('Guardian notifications could not be refreshed.',error?.code||error);}}
	function guardianNotificationText(item){const studentName=String(item.studentName||'').trim();if(state.language==='bn')return `${studentName||'শিক্ষার্থীর'} নতুন আপডেট শিক্ষক দিয়েছেন।`;return `Student ${studentName||''} has a new update from the teacher.`.replace(/Student  has/,'A student has');}
	async function openGuardianNotifications(){try{const unread=state.guardianNotifications.filter(item=>!item.readAt);if(unread.length)await Promise.all(unread.map(item=>markGuardianNotificationRead(state.user.uid,item.id)));await refreshGuardianNotifications();const notices=state.guardianNotifications;open(frame(txt('notifications'),state.language==='bn'?'সাম্প্রতিক শিক্ষক আপডেট':'Recent updates from the teacher',notices.length?`<div class="notification-list">${notices.map(item=>`<article class="notification-row"><span class="mini-avatar">${item.readAt?'✓':'●'}</span><div class="row-copy"><strong>${esc(guardianNotificationText(item))}</strong><span>${esc(item.subject||item.label||'')} · ${date(item.createdAt)}</span></div></article>`).join('')}</div>`:empty(txt('notifications'),txt('noNewNotifications'))),true);}catch(error){err(error);}}

async function login(intent='teacher'){state.intent=intent;try{await signInWithGoogle();}catch(error){err(error);}}
function startGuestMode(){openOfflineRiskModal();}
function openOfflineRiskModal(){const bn=state.language==='bn';open(`<section class="offline-risk-card" role="alertdialog" aria-modal="true" aria-labelledby="offlineRiskTitle"><div class="offline-risk-icon" aria-hidden="true">⚠</div><div class="offline-risk-content"><div class="offline-risk-heading"><div><h2 id="offlineRiskTitle">${bn?'গুরুত্বপূর্ণ: অফলাইন ডেটা ঝুঁকি':'Important: Offline data risk'}</h2><p>${bn?'Guest / Offline মোডে সব তথ্য শুধু এই ব্রাউজারে সংরক্ষিত হয়।':'In Guest / Offline mode, your information is stored only in this browser.'}</p></div><button type="button" class="modal-close" data-close aria-label="${bn?'বন্ধ করুন':'Close'}">×</button></div><div class="offline-risk-copy"><p>${bn?'ব্রাউজারের ডেটা মুছে গেলে, ডিভাইস নষ্ট হলে বা অ্যাপ আনইনস্টল করলে তথ্য হারিয়ে যেতে পারে।':'Your information may be lost if browser data is cleared, the device is damaged, or the app is uninstalled.'}</p><p>${bn?'নিয়মিত <strong>JSON ব্যাকআপ</strong> ডাউনলোড করে নিরাপদ জায়গায় রাখুন।':'Download a <strong>JSON backup</strong> regularly and keep it in a safe place.'}</p></div><div class="offline-risk-actions"><button type="button" class="btn btn-secondary" data-close>${bn?'বাতিল':'Cancel'}</button><button id="continueOfflineRisk" type="button" class="btn btn-primary" data-action="continue-offline-risk">${bn?'বুঝেছি, চালিয়ে যান':'I understand, continue'}</button></div></div></section>`);setTimeout(()=>$('#continueOfflineRisk')?.focus(),0);}
async function authChanged(user){if(state.authTimer){clearTimeout(state.authTimer);state.authTimer=null;}cleanUnsubscribe();state.user=user;state.profile=null;state.students=[];state.batches=[];state.requests=[];state.activities=[];state.tasks=[];if(!user){state.intent='teacher';state.guardianRoom=null;state.guardianState=null;show('signInScreen');syncLanguage();return;}try{state.profile=await ensureProfile(user);if(state.profile.status==='blocked'){await signOutUser();toast(state.language==='bn'?'অ্যাকাউন্টটি ব্লক করা হয়েছে।':'This account has been blocked.','error');return;}state.roles=await getRoles(user);if(state.intent==='guardian'){show('guardianScreen');renderGuardian();return;}show('teacherShell');setupTeacher();}catch(error){err(error);show('signInScreen');}}
function setupTeacher(){ $('#profileName').textContent=state.profile?.name||state.user?.displayName||'Teacher';$('#profileEmail').textContent=state.user?.email||'';$('#profileInitial').textContent=initials(state.profile?.name||state.user?.displayName);$('#adminNav').classList.toggle('hidden',!state.roles.isAdmin);$('#libraryNav').classList.toggle('hidden',!state.roles.isAdmin);if(!state.roles.isAdmin&&(state.view==='library'||state.view==='admin'))state.view='dashboard';state.stopConnection=subscribeConnectionState(updateSyncStatus);state.stop=subscribeTeacherWorkspace(state.user.uid,{students:items=>{state.students=recent(items);render();},batches:items=>{state.batches=recent(items);render();},requests:items=>{state.requests=recent(items);const count=items.filter(x=>x.status==='pending').length;$('#requestBadge').textContent=count;$('#requestBadge').classList.toggle('hidden',!count);render();},activity:items=>{state.activities=recent(items);render();},tasks:items=>{state.tasks=recent(items,'dueDate');render();},error:err});render();}

function render(){if(!state.user||state.intent!=='teacher')return;$('#viewTitle').textContent=viewName(state.view);if(state.selectedStudent){renderStudent();return;}if(state.selectedBatch){renderBatch();return;}if(state.view==='students')renderStudents();else if(state.view==='batches')renderBatches();else if(state.view==='requests')renderRequests();else if(state.view==='plans')renderPlans();else if(state.view==='library')renderLibrary();else if(state.view==='admin')renderAdmin();else renderDashboard();}
function metric(icon,label,value,detail,tone=''){return `<article class="metric-card ${tone}"><div class="metric-top"><span>${esc(label)}</span><span class="metric-icon">${icon}</span></div><div class="metric-value">${esc(value)}</div><p class="metric-detail">${esc(detail)}</p></article>`;}
function empty(title,body,button=''){return `<div class="empty-state"><strong>${esc(title)}</strong><p>${esc(body)}</p>${button}</div>`;}
function cardHeading(kicker,title,action=''){return `<div class="card-heading"><div><p class="eyebrow">${esc(kicker)}</p><h3>${esc(title)}</h3></div>${action}</div>`;}
function renderDashboard(){const pending=state.requests.filter(x=>x.status==='pending');const studentCount=state.students.length;const batchCount=state.batches.length;const pendingCount=pending.length;const card=(icon,title,count,description,view,action,accent)=>`<article class="launch-card ${accent||''}"><div class="launch-card-top"><span class="launch-icon">${icon}</span><span class="launch-count">${num(count)}</span></div><h3>${title}</h3><p>${description}</p><div class="launch-actions"><button class="btn btn-primary" data-view="${view}">খুলুন <span aria-hidden="true">→</span></button>${action?`<button class="small-btn" data-action="${action}">＋ যোগ করুন</button>`:''}</div></article>`;root.innerHTML=`<section class="page-heading"><div><p class="eyebrow">${state.user?.mode==='guest'?'Guest / Offline':'শিক্ষক কর্মক্ষেত্র'}</p><h2>${state.language==='bn'?'আজকের কাজ এক নজরে':'Today at a glance'}</h2><p>${state.language==='bn'?'শিক্ষার্থী, ব্যাচ ও অভিভাবকের প্রয়োজনীয় জায়গায় সরাসরি যান।':'Go directly to students, batches, or guardian requests.'}</p></div><div class="heading-actions"><button class="btn btn-primary" data-action="quick-log">＋ ${txt('addDailyUpdate')}</button></div></section><section class="launch-grid">${card('◉',state.language==='bn'?'শিক্ষার্থী':'Students',studentCount,state.language==='bn'?'নাম, সাপ্তাহিক শিট, চেকলিস্ট ও পরীক্ষা':'Names, weekly sheets, checklists, and exams','students','new-student','blue')}${card('▦',state.language==='bn'?'ব্যাচ':'Batches',batchCount,state.language==='bn'?'ব্যাচের সময়সূচি, নোট ও ক্লাস রেকর্ড':'Schedules, notes, and class records','batches','new-batch','teal')}${card('♧',state.language==='bn'?'অভিভাবক':'Guardians',pendingCount,pendingCount?`${num(pendingCount)} ${state.language==='bn'?'টি অনুরোধ অপেক্ষায়':'request(s) waiting'}`:state.language==='bn'?'নতুন অনুরোধ এখানে দেখা যাবে':'New requests will appear here','requests',null,'orange')}</section><section class="dashboard-grid"><div class="stack"><article class="card">${cardHeading(txt('currentWeek'),txt('progressInsights'),`<button class="small-link" data-view="plans">${txt('view')} →</button>`)}${chart()}</article><article class="card">${cardHeading(txt('recentActivity'),state.language==='bn'?'সাম্প্রতিক কাজ':'Recent work')}${activities()}</article></div><div class="stack"><article class="card upcoming-card">${cardHeading(txt('upcomingWork'),state.language==='bn'?'আজকের ফোকাস':'Today’s focus',`<button class="small-link" data-action="new-task">＋</button>`)}${todayFocus()}</article><article class="card">${cardHeading(txt('pendingRequests'),state.language==='bn'?'অভিভাবক অনুরোধ':'Guardian requests',`<button class="small-link" data-view="requests">${txt('view')} →</button>`)}${pending.length?`<div class="request-list">${pending.slice(0,3).map(requestRow).join('')}</div>`:empty(txt('noPendingRequests'),state.language==='bn'?'নতুন অনুরোধ এখানে দেখা যাবে।':'New requests will appear here.')}</article></div></section>`;} function chart(){const today=new Date();today.setHours(0,0,0,0);const days=Array.from({length:7},(_,index)=>{const day=new Date(today);day.setDate(today.getDate()-6+index);return day;});const totals=days.map(()=>0);state.activities.forEach(item=>{const raw=item.createdAt;const value=raw?.toDate?raw.toDate():raw?.seconds?new Date(raw.seconds*1000):new Date(raw);if(Number.isNaN(value?.getTime?.()))return;value.setHours(0,0,0,0);const offset=Math.round((value-today)/86400000)+6;if(offset>=0&&offset<7)totals[offset]+=1;});const total=totals.reduce((sum,value)=>sum+value,0);const activeDays=totals.filter(Boolean).length;const target=Math.max(1,state.students.length);const coverage=Math.min(100,Math.round(total/Math.max(1,target*3)*100));return `<div class="dashboard-chart-layout"><div class="chart-pane"><div class="chart-scale"><span>${state.language==='bn'?'ভালো':'Strong'}</span><span>${state.language==='bn'?'আংশিক':'Partial'}</span><span>${state.language==='bn'?'বাকি':'Due'}</span></div><div class="chart-area activity-chart">${totals.map((value,index)=>{const dayScore=Math.min(100,Math.round(value/target*100));const height=value?Math.max(18,Math.round(dayScore)):6;const status=dayScore>=80?'good':dayScore>0?'partial':'due';const label=state.language==='bn'?days[index].toLocaleDateString('bn-BD',{weekday:'narrow'}):days[index].toLocaleDateString('en-US',{weekday:'narrow'});const statusText=state.language==='bn'?(status==='good'?'ভালো':status==='partial'?'আংশিক':'বাকি'):(status==='good'?'Strong':status==='partial'?'Partial':'Due');return `<div class="bar-group" data-status="${status}" title="${esc(statusText)} · ${value} ${state.language==='bn'?'টি আপডেট':'updates'}" aria-label="${esc(label)}: ${esc(statusText)}"><span class="bar-value">${value||''}</span><div class="bar bar-${status}" style="height:${height}%"></div><span class="bar-status">${esc(statusText)}</span><span class="bar-label">${label}</span></div>`;}).join('')}</div><div class="chart-legend"><span><i class="dot dot-red"></i>${state.language==='bn'?'কাজ বাকি':'Due'}</span><span><i class="dot dot-amber"></i>${state.language==='bn'?'আংশিক':'Partial'}</span><span><i class="dot dot-green"></i>${state.language==='bn'?'ভালো':'Strong'}</span></div></div><aside class="weekly-signal"><div class="signal-ring" style="--signal:${coverage}%"><span>${coverage}%</span></div><div><strong>${state.language==='bn'?'সাপ্তাহিক ধারাবাহিকতা':'Weekly rhythm'}</strong><p>${state.language==='bn'?`${activeDays}/7 দিন আপডেট লেখা হয়েছে`:`Updates recorded on ${activeDays}/7 days`}</p></div></aside></div>`;}
function activities(){if(!state.activities.length)return empty(txt('noData'),state.language==='bn'?'প্রথম শিক্ষার্থী বা শেখার নথি যোগ করে শুরু করুন।':'Start by adding a student or a learning log.');return `<div class="activity-list">${state.activities.slice(0,6).map(item=>`<div class="activity-row"><span class="mini-avatar">${item.type?.includes('batch')?'▦':item.type?.includes('guardian')?'♧':item.type?.includes('assessment')?'★':'◉'}</span><div class="row-copy"><strong>${esc(activityText(item))}</strong><span>${date(item.createdAt)}</span></div></div>`).join('')}</div>`;}
function activityText(item){const map={'student-created':state.language==='bn'?'শিক্ষার্থী যোগ করা হয়েছে':'Student added','daily-log-added':state.language==='bn'?'দৈনিক শেখার নথি যোগ হয়েছে':'Daily learning log added','batch-created':state.language==='bn'?'ব্যাচ তৈরি হয়েছে':'Batch created','batch-session-recorded':state.language==='bn'?'ব্যাচ সেশন সংরক্ষণ হয়েছে':'Batch session saved','guardian-requested':state.language==='bn'?'অভিভাবক অনুরোধ এসেছে':'Guardian request received','guardian-approved':state.language==='bn'?'অভিভাবক অনুমোদিত':'Guardian approved'};return `${map[item.type]||txt('updated')}${item.details?.name?` · ${item.details.name}`:''}`;}
const studentJourney = createStudentJourney({
  state, root, txt, esc, date, metric, cardHeading, empty, open, close, frame,
  input, area, select, actions, toast, err, logModal,
});

function taskStatusLabel(status){return state.language==='bn'?(status==='done'?'সম্পন্ন':'বাকি'):(status==='done'?'Done':'Due');}
function taskRows(){const tasks=state.tasks.slice().sort((a,b)=>time(a.dueDate||a.createdAt)-time(b.dueDate||b.createdAt));if(!tasks.length)return empty(state.language==='bn'?'কোনো পরিকল্পিত কাজ নেই':'No planned work yet',state.language==='bn'?'＋ চাপ দিয়ে শিক্ষার্থী বা ব্যাচের জন্য কাজ নির্ধারণ করুন।':'Use + to plan work for an individual student or batch.',`<button class="btn btn-secondary" data-action="new-task">＋ ${state.language==='bn'?'কাজ নির্ধারণ':'Plan work'}</button>`);const now=new Date();return `<div class="planner-list">${tasks.slice(0,6).map(item=>{const targetType=item.kind==='batch'?'batch':'student';const targetLabel=item.kind==='batch'?(state.language==='bn'?'ব্যাচ':'Batch'):(state.language==='bn'?'শিক্ষার্থী':'Student');const due=item.dueDate?date(item.dueDate):(state.language==='bn'?'তারিখ নেই':'No date');const overdue=item.status!=='done'&&item.dueDate&&new Date(`${item.dueDate}T23:59:59`)<now;const statusText=overdue?(state.language==='bn'?'মেয়াদ পেরিয়েছে':'Overdue'):taskStatusLabel(item.status);return `<article class="planner-row ${item.status==='done'?'is-done':'is-due'} ${overdue?'is-overdue':''}"><button class="task-check" data-action="toggle-task" data-id="${esc(item.id)}" aria-label="${esc(statusText)}">${item.status==='done'?'✓':'!'}</button><div class="row-copy"><strong>${esc(item.title)}</strong><button class="task-target" data-action="task-target" data-target-type="${targetType}" data-target-id="${esc(item.targetId)}"><span>${esc(targetLabel)}</span> · ${esc(item.targetName||'')} · ${esc(due)}</button></div><span class="task-status">${esc(statusText)}</span></article>`;}).join('')}</div>`;}
function todayFocus(){return `<div class="focus-shortcuts"><button class="focus-shortcut" data-action="new-task-student"><span>◉</span><strong>${state.language==='bn'?'শিক্ষার্থীর কাজ':'Student work'}</strong><small>${state.language==='bn'?'ব্যক্তিগত পরিকল্পনা':'Individual plan'}</small></button><button class="focus-shortcut" data-action="new-task-batch"><span>▦</span><strong>${state.language==='bn'?'ব্যাচের কাজ':'Batch work'}</strong><small>${state.language==='bn'?'একসঙ্গে পরিকল্পনা':'Shared plan'}</small></button></div>${taskRows()}`;}
function requestRow(item){return `<div class="request-row"><span class="mini-avatar">${esc(initials(item.guardianName||'Guardian'))}</span><div class="row-copy"><strong>${esc(item.guardianName||'Guardian')}</strong><span>${esc(item.roomName||'')} · ${date(item.requestedAt)}</span></div><div class="row-actions"><button class="small-btn approve" data-action="approve" data-id="${esc(item.id)}">${txt('approve')}</button><button class="small-btn reject" data-action="reject" data-id="${esc(item.id)}">${txt('reject')}</button></div></div>`;}

function renderStudents(){root.innerHTML=`<section class="page-heading"><div><p class="eyebrow">${txt('students')}</p><h2>${state.language==='bn'?'শিক্ষার্থীর তালিকা':'Student directory'}</h2><p>${state.language==='bn'?'প্রতিটি শিক্ষার্থীর জন্য আলাদা শেখার পরিকল্পনা, চেকলিস্ট এবং মূল্যায়ন রাখুন।':'Give every learner an individual plan, checklist, and assessment history.'}</p></div><div class="heading-actions"><button class="btn btn-primary" data-action="new-student">＋ ${txt('createStudent')}</button></div></section><div class="data-toolbar"><div class="search-box"><input id="studentSearch" type="search" placeholder="${esc(state.language==='bn'?'শিক্ষার্থীর নাম দিয়ে খুঁজুন':'Search by student name')}"></div></div><div id="studentGrid" class="student-grid">${studentCards(state.students)}</div>`;$('#studentSearch')?.addEventListener('input',event=>{const term=event.target.value.toLowerCase();$('#studentGrid').innerHTML=studentCards(state.students.filter(s=>String(s.name||'').toLowerCase().includes(term)));});}
function studentCards(students){if(!students.length)return empty(txt('noStudents'),state.language==='bn'?'একজন শিক্ষার্থী যোগ করে শুরু করুন।':'Add a learner to start.',`<button class="btn btn-primary" data-action="new-student">＋ ${txt('createStudent')}</button>`);return students.map(student=>{const progress=Math.max(0,Math.min(100,Number(student.progress||0)));const photo=student.photoUrl||student.photo||'';const note=student.note||student.message||'';const school=student.schoolName||student.school||'';const subjects=(student.subjects||[]).map(x=>x.name||x).slice(0,2).join(' · ');const updated=student.updatedAt||student.lastUpdated||student.lastActive||'';return `<article class="student-card reference-student-card" data-action="open-student" data-id="${esc(student.id)}"><div class="student-card-top"><span class="student-avatar reference-avatar">${photo?`<img src="${esc(photo)}" alt="">`:esc(initials(student.name))}</span><div class="student-card-identity"><h3>${esc(student.name)}</h3><p>${esc([school,student.grade].filter(Boolean).join(' · ')||(state.language==='bn'?'শ্রেণি নির্ধারণ হয়নি':'Class not set'))}</p>${note?`<small>${esc(note)}</small>`:''}</div><span class="student-card-chevron">›</span></div><div class="student-card-tags">${subjects?`<span class="student-tag">${esc(subjects)}</span>`:''}<span class="student-tag">${progress>=80?(state.language==='bn'?'ভালো অগ্রগতি':'Good progress'):progress>0?(state.language==='bn'?'চলমান':'In progress'):(state.language==='bn'?'শুরু হয়নি':'Not started')}</span></div><div class="progress-line reference-progress"><div class="progress-track"><div class="progress-fill" style="width:${progress}%"></div></div><span class="progress-percent">${progress}%</span></div><div class="student-card-footer"><span>${updated?`${state.language==='bn'?'সর্বশেষ আপডেট':'Updated'}: ${esc(date(updated))}`:(state.language==='bn'?'আজকের অগ্রগতি লিখুন':'Add today’s progress')}</span><span>${student.batchIds?.length?`▦ ${student.batchIds.length} ${state.language==='bn'?'ব্যাচ':'batch'}`:''}</span></div></article>`}).join('');}
function renderStudent(){ studentJourney.render(); }
function renderBatches(){root.innerHTML=`<section class="page-heading"><div><p class="eyebrow">${txt('batches')}</p><h2>${state.language==='bn'?'ব্যাচ ও ক্লাস':'Batches and classes'}</h2><p>${state.language==='bn'?'একবারের সেশন আপডেট, দ্রুত উপস্থিতি এবং প্রয়োজন হলে ব্যক্তিগত নোট।':'One shared session update, quick attendance, and private notes only when needed.'}</p></div><div class="heading-actions"><button class="btn btn-primary" data-action="new-batch">＋ ${txt('createBatch')}</button></div></section><div class="batch-grid">${batchCards()}</div>`;}
function batchCards(){if(!state.batches.length)return empty(txt('noBatches'),state.language==='bn'?'একটি ব্যাচ তৈরি করে একই পাঠ একসঙ্গে পরিচালনা করুন।':'Create a batch to run shared lessons.',`<button class="btn btn-primary" data-action="new-batch">＋ ${txt('createBatch')}</button>`);return state.batches.map(batch=>`<article class="batch-card" data-action="open-batch" data-id="${esc(batch.id)}"><div class="batch-card-top"><span class="student-avatar">▦</span><div><h3>${esc(batch.name)}</h3><p>${esc(batch.grade||'')}</p></div></div><div class="progress-line"><div class="progress-track"><div class="progress-fill" style="width:${Number(batch.coverage||0)}%"></div></div><span class="progress-percent">${Number(batch.coverage||0)}%</span></div><div class="batch-card-footer"><span>${batch.memberIds?.length||0} ${state.language==='bn'?'শিক্ষার্থী':'students'}</span><span class="tag ${batch.accessMode===RoomAccessMode.IMMEDIATE?'green':'orange'}">${batch.accessMode===RoomAccessMode.IMMEDIATE?txt('immediateBatchAccess'):txt('approvalRequired')}</span></div></article>`).join('');}
function batchRoomPanel(batch){const bn=state.language==='bn';if(!batch.roomCode)return `<article class="room-code-panel room-code-empty"><div><p class="eyebrow">${txt('roomCode')}</p><h3>${bn?'অভিভাবকের জন্য ব্যাচ রুম তৈরি করুন':'Create the batch room for guardians'}</h3><p>${bn?'কোড তৈরি হলে এটি এই পাতায় স্থায়ীভাবে দেখা যাবে।':'After creation, the code stays visible on this page.'}</p></div><button class="btn btn-primary" data-action="batch-room" data-id="${esc(batch.id)}">${txt('createRoom')}</button></article>`;return `<article class="room-code-panel"><div class="room-code-copy"><p class="eyebrow">${txt('roomCode')}</p><strong class="room-code-value">${esc(batch.roomCode)}</strong><p>${txt('roomCodeSaved')}</p></div><div class="room-code-actions"><button class="btn btn-secondary" data-action="copy-room-code" data-code="${esc(batch.roomCode)}">${txt('copyCode')}</button><button class="btn btn-primary" data-action="share-room-code" data-code="${esc(batch.roomCode)}" data-name="${esc(batch.name)}">${txt('shareCode')}</button></div></article>`;}
async function renderBatch(){const batch=state.batches.find(x=>x.id===state.selectedBatch);if(!batch){state.selectedBatch=null;renderBatches();return;}let sessions=[];try{sessions=recent(await listBatchSessions(batch.id));}catch(error){console.warn(error);}const members=state.students.filter(s=>(batch.memberIds||[]).includes(s.id));root.innerHTML=`<section class="batch-hero"><span class="hero-avatar">▦</span><div class="hero-copy"><p class="eyebrow">${esc(batch.grade||txt('batches'))}</p><h2>${esc(batch.name)}</h2><p>${esc(batch.description||(state.language==='bn'?'ভাগ করা শেখার পরিকল্পনা':'Shared learning plan'))}</p></div><div class="hero-actions"><button class="btn btn-secondary" data-action="back-batches">← ${txt('batches')}</button><button class="btn btn-secondary" data-action="batch-room" data-id="${esc(batch.id)}">${batch.roomCode?txt('shareCode'):txt('createRoom')}</button><button class="btn btn-primary" data-action="record-session" data-id="${esc(batch.id)}">＋ ${txt('recordSession')}</button></div></section>${batchRoomPanel(batch)}<div class="two-col"><article class="card">${cardHeading(txt('batchSessions'),state.language==='bn'?'সাম্প্রতিক সেশন':'Recent sessions',`<button class="btn btn-primary" data-action="record-session" data-id="${esc(batch.id)}">＋ ${txt('recordSession')}</button>`)}${sessions.length?`<div class="log-list">${sessions.slice(0,5).map(s=>`<article class="log-card"><div class="log-top"><strong>${esc((s.subjects||[]).join(' · ')||batch.name)} · ${esc(s.topics||'')}</strong><small>${date(s.date||s.createdAt)}</small></div><p>${esc(s.homework||s.notice||'')}</p></article>`).join('')}</div>`:empty(txt('noData'),state.language==='bn'?'প্রথম সেশন লিখুন।':'Record the first session.')}</article><article class="card">${cardHeading(txt('batchMembers'),`${members.length} ${state.language==='bn'?'শিক্ষার্থী':'students'}`)}${members.length?`<div class="student-list">${members.map(s=>`<div class="student-row"><span class="mini-avatar">${esc(initials(s.name))}</span><div class="row-copy"><strong>${esc(s.name)}</strong><span>${esc(s.grade||'')}</span></div><button class="small-btn" data-action="open-student" data-id="${esc(s.id)}">${txt('view')}</button></div>`).join('')}</div>`:empty(txt('noData'),state.language==='bn'?'ব্যাচ তৈরির সময় শিক্ষার্থী বেছে নিন।':'Choose students while creating the batch.')}</article></div>`;}

function roomShareRows(){const rooms=[...state.students.map(item=>({type:'student',id:item.id,name:item.name,detail:item.grade,roomCode:item.roomCode})),...state.batches.map(item=>({type:'batch',id:item.id,name:item.name,detail:item.grade,roomCode:item.roomCode}))];if(!rooms.length)return empty(txt('noData'),state.language==='bn'?'প্রথমে শিক্ষার্থী বা ব্যাচ তৈরি করুন।':'Create a student or batch first.');return `<div class="room-share-list">${rooms.map(room=>{const student=room.type==='student';const label=student?(state.language==='bn'?'ব্যক্তিগত শিক্ষার্থী':'Individual learner'):(state.language==='bn'?'শেয়ার করা ব্যাচ':'Shared batch');const action=student?'student-room':'batch-room';return `<article class="room-share-row"><span class="mini-avatar">${student?'◉':'▦'}</span><div class="row-copy"><strong>${esc(room.name)}</strong><span>${esc(label)}${room.detail?` · ${esc(room.detail)}`:''}</span></div><code class="share-code">${esc(room.roomCode||'—')}</code><button class="small-btn ${room.roomCode?'':'approve'}" data-action="${action}" data-id="${esc(room.id)}">${room.roomCode?(state.language==='bn'?'নতুন কোড':'New code'):txt('createRoom')}</button></article>`;}).join('')}</div>`;}
	function renderRequests(){const pending=state.requests.filter(x=>x.status==='pending');const history=state.requests.filter(x=>x.status!=='pending');root.innerHTML=`<section class="page-heading"><div><p class="eyebrow">${txt('requests')}</p><h2>${state.language==='bn'?'অভিভাবক অনুমতি ও শেয়ার কোড':'Guardian permission and share codes'}</h2><p>${state.language==='bn'?'প্রথমে এখানে রুম কোড তৈরি করুন। অভিভাবক Google দিয়ে সাইন ইন করে কোড দিলে তাদের অনুরোধ নিচে দেখা যাবে।':'Create a room code here first. After the guardian signs in with Google and enters it, their request appears below.'}</p></div></section><section class="dashboard-grid guardian-request-grid"><article class="card room-share-card">${cardHeading(txt('roomCode'),state.language==='bn'?'অভিভাবকের সঙ্গে কোড শেয়ার করুন':'Share a code with the guardian')}${roomShareRows()}<p class="privacy-note">${state.language==='bn'?'ব্যক্তিগত শিক্ষার্থীর জন্য অনুমোদন আবশ্যক। ব্যাচে তৈরি করার সময় নির্বাচিত প্রবেশের ধরন প্রযোজ্য হবে।':'Individual rooms always require approval. A batch uses the access mode chosen when it was created.'}</p></article><div class="stack"><article class="card">${cardHeading(txt('pendingRequests'),`${pending.length} ${state.language==='bn'?'টি সিদ্ধান্ত বাকি':'waiting'}`)}${pending.length?`<div class="request-list">${pending.map(requestRow).join('')}</div>`:empty(txt('noPendingRequests'),state.language==='bn'?'নতুন অনুরোধ এলে এখানে দেখা যাবে।':'New requests appear here.')}</article><article class="card">${cardHeading(txt('approved'),state.language==='bn'?'সাম্প্রতিক সিদ্ধান্ত':'Recent decisions')}${history.length?`<div class="request-list">${history.slice(0,6).map(r=>`<div class="request-row"><span class="mini-avatar">${esc(initials(r.guardianName))}</span><div class="row-copy"><strong>${esc(r.guardianName||'Guardian')}</strong><span>${esc(r.roomName||'')} · ${r.status==='approved'?txt('approved'):txt('reject')}</span></div></div>`).join('')}</div>`:empty(txt('noData'),state.language==='bn'?'এখনও কোনো সিদ্ধান্ত নেই।':'No decisions yet.')}</article></div></section>`;}
function renderPlans(){const bn=state.language==='bn';root.innerHTML=`<section class="page-heading"><div><p class="eyebrow">${txt('calendar')}</p><h2>${bn?'শিক্ষার্থীর শেখার কর্মক্ষেত্র':'Student learning workspace'}</h2><p>${bn?'একজন শিক্ষার্থীর নাম নির্বাচন করলে তার ট্র্যাক লিস্ট, সম্পন্নতার গ্রাফ, মূল্যায়ন ও সাপ্তাহিক পরিকল্পনা খুলবে।':'Choose a learner to open their track list, completion graph, assessments, and weekly plan.'}</p></div></section><article class="card workspace-picker-card">${cardHeading(txt('students'),bn?'একজন শিক্ষার্থী বেছে নিন':'Choose a learner')}${state.students.length?`<div class="student-list">${state.students.map(s=>`<button class="student-row" type="button" data-action="open-student" data-id="${esc(s.id)}"><span class="mini-avatar">${esc(initials(s.name))}</span><span class="row-copy"><strong>${esc(s.name)}</strong><span>${esc(s.grade||'')} · ${bn?'কর্মক্ষেত্র খুলুন':'Open workspace'}</span></span><span class="row-action">›</span></button>`).join('')}</div>`:empty(txt('noStudents'),bn?'প্রথমে একজন শিক্ষার্থী যোগ করুন।':'Add a student first.')}</article>`;}
async function renderLibrary(){root.innerHTML=empty(state.language==='bn'?'লাইব্রেরি লোড হচ্ছে…':'Loading library…','');try{state.curriculum=await listCurriculumVersions(state.roles.isAdmin);if(state.libraryVersion){await renderLibraryVersion(state.libraryVersion);return;}const bn=state.language==='bn';const button=state.roles.isAdmin?`<button class="btn btn-primary" data-action="new-version">＋ ${bn?'সংস্করণ যোগ করুন':'Add version'}</button>`:'';const versions=state.curriculum.filter(v=>state.roles.isAdmin||v.status==='published');root.innerHTML=`<section class="page-heading"><div><p class="eyebrow">${txt('library')}</p><h2>${txt('libraryTitle')}</h2><p>${bn?'প্রোগ্রাম, সংস্করণ, বই ও অধ্যায়ের একটি প্রকাশযোগ্য, আর্কাইভ-নিরাপদ লাইব্রেরি।':'A publishable, archive-safe library for programmes, versions, books, and chapters.'}</p></div><div class="heading-actions">${button}</div></section><article class="card">${cardHeading(txt('programme'),bn?'সংস্করণসমূহ':'Versions')}${versions.length?`<div class="student-list">${versions.map(v=>`<button type="button" class="student-row" data-action="manage-version" data-id="${esc(v.id)}"><span class="mini-avatar">▱</span><span class="row-copy"><strong>${esc(programmeLabel(v.programmeId,state.language))} · ${esc(v.name||v.academicYear||'')}</strong><span>${esc(v.academicYear||'')} · ${esc(txt(v.status||'draft'))} · ${bn?'বই ও অধ্যায় দেখুন':'View books and chapters'}</span></span><span class="row-action">›</span></button>`).join('')}</div>`:empty(txt('noData'),bn?'অ্যাডমিন প্রথম সংস্করণ যোগ করলে শিক্ষকরা তা টেমপ্লেট হিসেবে দেখতে পাবেন।':'Teachers can see the first version as a template after an administrator adds it.')}</article>`;}catch(error){err(error);}}
function adminAccountRow(account){const self=account.id===state.user?.uid;const status=account.isBlocked?txt('blockedAccount'):txt('activeAccount');const role=account.isAdmin?txt('administrator'):txt('teacherRole');const controls=self?`<span class="account-self">${state.language==='bn'?'বর্তমান অ্যাকাউন্ট':'Current account'}</span>`:`<div class="row-actions"><button class="small-btn ${account.isBlocked?'approve':'reject'}" data-action="${account.isBlocked?'admin-unblock':'admin-block'}" data-id="${esc(account.id)}">${account.isBlocked?txt('unblock'):txt('block')}</button><button class="small-btn" data-action="${account.isAdmin?'admin-demote':'admin-promote'}" data-id="${esc(account.id)}">${account.isAdmin?txt('removeAdmin'):txt('makeAdmin')}</button></div>`;return `<article class="admin-account-row"><span class="mini-avatar">${esc(initials(account.name||account.email||'A'))}</span><div class="row-copy"><strong>${esc(account.name||'Account')}</strong><span>${esc(account.email||account.id)}</span><div class="account-tags"><span class="tag ${account.isBlocked?'orange':'green'}">${esc(status)}</span><span class="tag ${account.isAdmin?'teal':''}">${esc(role)}</span></div></div>${controls}</article>`;}
	function securityAuditText(entry){const labels={account_blocked:state.language==='bn'?'অ্যাকাউন্ট ব্লক করা হয়েছে':'Account blocked',account_unblocked:state.language==='bn'?'অ্যাকাউন্ট আনব্লক করা হয়েছে':'Account unblocked',administrator_granted:state.language==='bn'?'অ্যাডমিন অধিকার দেওয়া হয়েছে':'Administrator access granted',administrator_removed:state.language==='bn'?'অ্যাডমিন অধিকার সরানো হয়েছে':'Administrator access removed'};const target=String(entry.details?.targetUid||'').slice(0,10);return `${labels[entry.type]||entry.type}${target?` · ${target}…`:''}`;}
	async function manageAdminAccount(action,id){if(!state.roles.isSuperAdmin)return;const account=state.adminAccounts.find(item=>item.id===id);if(!account)return;try{if(action==='admin-block')await setAccountBlocked(state.user.uid,account,true,'Blocked by super-admin');if(action==='admin-unblock')await setAccountBlocked(state.user.uid,account,false);if(action==='admin-promote')await setAdministratorRole(state.user.uid,account,true);if(action==='admin-demote')await setAdministratorRole(state.user.uid,account,false);toast(txt('updated'));renderAdmin();}catch(error){err(error);}}
	async function renderAdmin(){if(!state.roles.isAdmin){setView('dashboard');return;}const bn=state.language==='bn';const heading=`<section class="page-heading"><div><p class="eyebrow">${txt('admin')}</p><h2>${bn?'প্ল্যাটফর্ম প্রশাসন':'Platform administration'}</h2><p>${bn?'অ্যাডমিন কারিকুলাম ও প্ল্যাটফর্ম নিরাপত্তা দেখেন; কোনো শিক্ষার্থীর ব্যক্তিগত রিপোর্ট দেখতে পারেন না।':'Administrators manage curriculum and platform security; they cannot read any student-private report.'}</p></div></section>`;const curriculumCard=`<article class="card">${cardHeading(txt('library'),bn?'কারিকুলাম প্রশাসন':'Curriculum administration')}<p class="admin-copy">${bn?'নতুন বা সংশোধিত বই সবসময় নতুন সংস্করণ হিসেবে প্রকাশ করুন; পুরোনো সংস্করণ আর্কাইভ করুন, মুছবেন না।':'Publish each new or revised book as a new version; archive old versions rather than deleting them.'}</p><button class="btn btn-primary" data-view="library">${txt('library')}</button></article>`;if(!state.roles.isSuperAdmin){root.innerHTML=`${heading}<section class="two-col">${curriculumCard}<article class="card">${cardHeading(txt('exportData'),bn?'ডেটা সুরক্ষা':'Data protection')}<p class="admin-copy">${bn?'শিক্ষক তার নিজের ডেটার কপি নিতে পারেন। এই ভূমিকার জন্য কোনো অ্যাকাউন্ট বা শিক্ষার্থী-রিপোর্ট ব্যবস্থাপনার ক্ষমতা দেওয়া হয় না।':'Teachers can export their own data. This role has no account-management or student-report access.'}</p></article></section>`;return;}root.innerHTML=`${heading}<div class="page-loading">${bn?'অ্যাকাউন্ট তথ্য লোড হচ্ছে…':'Loading account information…'}</div>`;try{const [accounts,audit]=await Promise.all([listAdminAccounts(),listAdminAudit()]);if(state.view!=='admin'||!state.roles.isSuperAdmin)return;state.adminAccounts=recent(accounts,'lastActiveAt');state.adminAudit=recent(audit).filter(entry=>/^(account_|administrator_)/.test(entry.type));root.innerHTML=`${heading}<section class="admin-summary"><article class="card">${cardHeading(txt('accountManagement'),`${num(state.adminAccounts.length)} ${bn?'টি অ্যাকাউন্ট':'accounts'}`)}<p class="admin-copy">${bn?'অ্যাকাউন্টের সক্রিয় অবস্থা ও অ্যাডমিন ভূমিকা এখানে নিয়ন্ত্রণ করুন। নিজের অ্যাকাউন্ট থেকে নিজেকে ব্লক বা অ্যাডমিনমুক্ত করা যাবে না।':'Control account status and administrator roles here. Your own account cannot block or demote itself.'}</p></article><article class="card">${cardHeading(txt('securityLog'),`${num(state.adminAudit.length)} ${bn?'টি সাম্প্রতিক ঘটনা':'recent events'}`)}<p class="admin-copy">${bn?'এখানে কেবল অ্যাকাউন্ট-নিরাপত্তার ঘটনা দেখা যায়; শিক্ষার্থী, অভিভাবক বা রিপোর্টের কোনো তথ্য নয়।':'Only account-security events appear here; no student, guardian, or report data is displayed.'}</p></article></section><section class="admin-grid"><article class="card admin-accounts-card">${cardHeading(txt('accountManagement'),bn?'লাইভ অ্যাকাউন্ট ডিরেক্টরি':'Live account directory')}<div class="admin-account-list">${state.adminAccounts.length?state.adminAccounts.map(adminAccountRow).join(''):empty(txt('noData'),bn?'সাইন ইন করা অ্যাকাউন্টগুলো এখানে দেখা যাবে।':'Signed-in accounts will appear here.')}</div></article><article class="card admin-audit-card">${cardHeading(txt('securityLog'),bn?'সাম্প্রতিক নিয়ন্ত্রণ':'Recent controls')}<div class="activity-list">${state.adminAudit.length?state.adminAudit.slice(0,12).map(entry=>`<div class="activity-row"><span class="mini-avatar">⚙</span><div class="row-copy"><strong>${esc(securityAuditText(entry))}</strong><span>${date(entry.createdAt)}</span></div></div>`).join(''):empty(txt('noData'),bn?'এখনও কোনো অ্যাকাউন্ট-নিরাপত্তা ঘটনা নেই।':'No account-security events yet.')}</div></article></section><section class="two-col">${curriculumCard}<article class="card">${cardHeading(txt('exportData'),bn?'ডেটা সুরক্ষা':'Data protection')}<p class="admin-copy">${bn?'এই নিয়ন্ত্রণগুলো কেবল অ্যাকাউন্টের জন্য। শিক্ষার্থীর পরিকল্পনা, রিপোর্ট ও শেখার রেকর্ড আলাদা মালিকানা ও নিরাপত্তা নিয়মে সুরক্ষিত থাকে।':'These controls apply only to accounts. Student plans, reports, and learning records stay protected by separate ownership and security rules.'}</p></article></section>`;}catch(error){err(error);}}

function open(content,wide=false){$('#modalBody').innerHTML=content;modal.classList.toggle('modal-wide',wide);modal.showModal();}
function close(){modal.close();$('#modalBody').innerHTML='';}
function frame(title,desc,body){return `<div class="modal-card"><div class="modal-heading"><div><h2>${esc(title)}</h2>${desc?`<p>${esc(desc)}</p>`:''}</div><button type="button" class="modal-close" data-close>×</button></div>${body}</div>`;}
function input(label,name,value='',extra=''){return `<label class="field"><span>${esc(label)}</span><input name="${esc(name)}" value="${esc(value)}" ${extra}></label>`;}
function area(label,name,value='',extra=''){return `<label class="field"><span>${esc(label)}</span><textarea name="${esc(name)}" ${extra}>${esc(value)}</textarea></label>`;}
function select(label,name,items,value=''){return `<label class="field"><span>${esc(label)}</span><select name="${esc(name)}">${items.map(item=>`<option value="${esc(item.value)}" ${item.value===value?'selected':''}>${esc(item.label)}</option>`).join('')}</select></label>`;}
function actions(){return `<div class="modal-actions"><button class="btn btn-ghost" type="button" data-close>${txt('cancel')}</button><button class="btn btn-primary" type="submit">${txt('save')}</button></div>`;}
function quickAddModal(){const bn=state.language==='bn';open(frame(bn?'দ্রুত যোগ করুন':'Quick add',bn?'আপনি কী যোগ করতে চান?':'What would you like to add?',`<div class="quick-actions"><button class="quick-action" type="button" data-action="new-student"><span>＋</span><strong>${txt('createStudent')}</strong></button><button class="quick-action" type="button" data-action="new-batch"><span>▦</span><strong>${txt('createBatch')}</strong></button><button class="quick-action" type="button" data-action="new-task"><span>◷</span><strong>${bn?'পরিকল্পিত কাজ':'Plan due work'}</strong></button><button class="quick-action" type="button" data-action="quick-log"><span>✎</span><strong>${txt('addDailyUpdate')}</strong></button></div>`));}
function taskModal(kind=''){const bn=state.language==='bn';const options=[...state.students.map(item=>({value:`student:${item.id}`,label:`◉ ${item.name}`})),...state.batches.map(item=>({value:`batch:${item.id}`,label:`▦ ${item.name}`}))];const filteredOptions=kind?options.filter(item=>item.value.startsWith(`${kind}:`)):options;if(!filteredOptions.length){toast(bn?'আগে একজন শিক্ষার্থী বা ব্যাচ যোগ করুন।':'Add a student or batch first.','error');return;}open(frame(bn?'কাজ নির্ধারণ':'Plan due work',bn?'আজকের ফোকাসে কোন কাজটি দেখা যাবে তা লিখুন।':'Choose what should appear in Today’s focus.',`<form id="taskForm"><div class="form-grid">${input(bn?'কাজের নাম':'Work title','title','','required placeholder="উদাহরণ: গণিতের অনুশীলন"')}${select(bn?'কার জন্য':'For', 'target', filteredOptions)}${input(bn?'শেষ করার তারিখ':'Due date','dueDate',new Date().toISOString().slice(0,10),'type="date"')}</div>${actions()}</form>`));$('#taskForm').onsubmit=async event=>{event.preventDefault();const form=new FormData(event.currentTarget);const [kind,targetId]=String(form.get('target')||'').split(':');const target=(kind==='batch'?state.batches:state.students).find(item=>item.id===targetId);try{await createTeacherTask(state.user.uid,{title:form.get('title'),kind,targetId,targetName:target?.name||'',dueDate:form.get('dueDate'),status:'due'});close();toast(bn?'কাজ নির্ধারণ করা হয়েছে।':'Work planned.');}catch(error){err(error);}};}
function studentModal(){open(frame(txt('createStudent'),state.language==='bn'?'নিজস্ব বিষয় দিয়ে শুরু করুন; পরে রোডম্যাপ ও টেমপ্লেট যোগ করতে পারবেন।':'Start with custom subjects; roadmaps and templates can be added later.',`<form id="studentForm"><div class="form-grid">${input(txt('studentName'),'name','','required')}${input(txt('classOrGrade'),'grade')}${area(txt('customSubjects'),'subjects','','placeholder="Math, English, Bangla"')}${area(txt('parentNote'),'note')}</div><div class="privacy-note">${txt('customSubjectsHint')}</div>${actions()}</form>`));$('#studentForm').onsubmit=async event=>{event.preventDefault();const f=new FormData(event.currentTarget);try{await createStudent(state.user.uid,{name:f.get('name'),grade:f.get('grade'),note:f.get('note'),subjects:String(f.get('subjects')||'').split(',').map(name=>({name:name.trim()}))});close();toast(txt('studentCreated'));setView('students');}catch(error){err(error);}};}
function batchModal(){const members=state.students.map(s=>`<label class="check-row"><input type="checkbox" name="member" value="${esc(s.id)}">${esc(s.name)} <small>${esc(s.grade||'')}</small></label>`).join('')||`<span>${esc(txt('noStudents'))}</span>`;open(frame(txt('createBatch'),state.language==='bn'?'একবারের সেশন আপডেট, দ্রুত উপস্থিতি, এবং শুধু প্রয়োজন হলে ব্যক্তিগত নোট।':'One shared update, quick attendance, and private notes only when needed.',`<form id="batchForm"><div class="form-grid">${input(txt('batchName'),'name','','required')}${input(txt('classOrGrade'),'grade')}${area(txt('batchDescription'),'description')}${input(txt('customSubjects'),'subjects','','placeholder="Math, English"')}${select(txt('accessMode'),'accessMode',[{value:RoomAccessMode.APPROVAL,label:txt('approvalRequired')},{value:RoomAccessMode.IMMEDIATE,label:txt('immediateBatchAccess')}])}<div class="field full"><span>${txt('batchMembers')}</span><div class="checkbox-list">${members}</div></div></div><div class="privacy-note">${txt('immediateAccessHelp')}</div>${actions()}</form>`),true);$('#batchForm').onsubmit=async event=>{event.preventDefault();const f=new FormData(event.currentTarget);const memberIds=f.getAll('member');const studentBatchIds=Object.fromEntries(state.students.map(s=>[s.id,s.batchIds||[]]));try{const created=await createBatch(state.user.uid,{name:f.get('name'),grade:f.get('grade'),description:f.get('description'),subjects:String(f.get('subjects')||'').split(',').map(x=>x.trim()).filter(Boolean),accessMode:f.get('accessMode'),memberIds,studentBatchIds},state.profile?.name);state.batches=recent([created,...state.batches.filter(item=>item.id!==created.id)]);close();toast(state.language==='bn'?'ব্যাচ তৈরি হয়েছে।':'Batch created.');setView('batches');}catch(error){err(error);}};}
function chooseStudent(next){open(frame(txt('chooseStudent'),'',`<div class="student-list">${state.students.map(s=>`<button class="student-row" type="button" data-pick="${esc(s.id)}"><span class="mini-avatar">${esc(initials(s.name))}</span><span class="row-copy"><strong>${esc(s.name)}</strong><span>${esc(s.grade||'')}</span></span></button>`).join('')||empty(txt('noStudents'),txt('noStudents'))}</div>`));$$('[data-pick]').forEach(b=>b.onclick=()=>{close();next(b.dataset.pick);});}
function logModal(studentId=''){if(!studentId){if(!state.students.length){studentModal();return;}chooseStudent(logModal);return;}const student=state.students.find(s=>s.id===studentId);if(!student)return;const subjects=(student.subjects||[]).map(s=>String(s?.name||s?.label||s?.title||s||'').trim()).filter(Boolean).map(name=>({value:name,label:name}));open(frame(txt('addLog'),`${student.name} · ${txt('dailyLog')}`,`<form id="logForm"><div class="form-grid">${select(txt('subject'),'subject',subjects)}${input(txt('lessonTopic'),'topic','','required')}${input(txt('learningProgress'),'learning','3','type="number" min="0" max="5" required')}${input(txt('homeworkCompletionRating'),'homeworkRating','3','type="number" min="0" max="5" required')}${input(txt('attentionParticipation'),'attention','3','type="number" min="0" max="5" required')}${input(state.language==='bn'?'তারিখ':'Date','logDate',new Date().toISOString().slice(0,10),'type="date"')}${area(txt('homework'),'homework')}${area(txt('teacherNote'),'note')}</div>${actions()}</form>`));$('#logForm').onsubmit=async event=>{event.preventDefault();const form=new FormData(event.currentTarget);try{const {addDailyLog}=await import('./demo-service.js?v=4.8.3');await addDailyLog(state.user.uid,studentId,Object.fromEntries(form));close();toast(txt('updated'));}catch(error){err(error);}};}
function sessionModal(batchId){const batch=state.batches.find(b=>b.id===batchId);if(!batch)return;const members=state.students.filter(s=>(batch.memberIds||[]).includes(s.id));open(frame(txt('recordSession'),batch.name,`<form id="sessionForm"><div class="form-grid">${select(txt('subject'),'subject',(batch.subjects||[]).map(s=>({value:s,label:s})))}${input(state.language==='bn'?'তারিখ':'Date','date',new Date().toISOString().slice(0,10),'type="date"')}${area(txt('lessonTopic'),'topics')}${area(txt('homework'),'homework')}<div class="field full"><span>${txt('batchMembers')}</span><table class="roster-table"><thead><tr><th>${txt('students')}</th><th>${txt('attendance')}</th><th>${txt('homework')}</th><th>${txt('privateNote')}</th></tr></thead><tbody>${members.map(s=>`<tr><td>${esc(s.name)}<input type="hidden" name="student" value="${esc(s.id)}"></td><td><select name="attendance"><option value="present">${txt('present')}</option><option value="absent">${txt('absent')}</option><option value="late">${txt('late')}</option></select></td><td><select name="homeworkStatus"><option value="not-recorded">—</option><option value="done">${txt('homeworkDone')}</option><option value="missing">${txt('homeworkMissing')}</option></select></td><td><input name="privateNote"></td></tr>`).join('')}</tbody></table></div></div>${actions()}</form>`),true);$('#sessionForm').onsubmit=async event=>{event.preventDefault();const f=new FormData(event.currentTarget);const ids=f.getAll('student'),attendance=f.getAll('attendance'),homework=f.getAll('homeworkStatus'),notes=f.getAll('privateNote');try{await recordBatchSession(state.user.uid,batch.id,{date:f.get('date'),subjects:[f.get('subject')],topics:f.get('topics'),homework:f.get('homework'),roster:ids.map((id,i)=>({studentId:id,attendance:attendance[i],homework:homework[i],privateNote:notes[i]}))},members);close();toast(txt('updated'));renderBatch();}catch(error){err(error);}};}
function versionModal(){const options=PROGRAMMES.map(p=>({value:p.id,label:p[state.language]}));open(frame(state.language==='bn'?'কারিকুলাম সংস্করণ যোগ করুন':'Add curriculum version',state.language==='bn'?'নতুন বই বা পরিবর্তিত বই সবসময় নতুন সংস্করণে প্রকাশ করুন; পুরোনোটি মুছবেন না।':'Publish each new or revised book as a new version; never overwrite the old version.',`<form id="versionForm"><div class="form-grid">${select(txt('programme'),'programmeId',options)}${input(txt('version'),'name','','required placeholder="NCTB 2027 Revised"')}${input(state.language==='bn'?'শিক্ষাবর্ষ':'Academic year','academicYear','','required')}${select(state.language==='bn'?'অবস্থা':'Status','status',[{value:'draft',label:txt('draft')},{value:'published',label:txt('published')}])}${input(state.language==='bn'?'উৎস লিংক':'Source URL','sourceUrl')}${area(state.language==='bn'?'নোট':'Notes','notes')}</div>${actions()}</form>`));$('#versionForm').onsubmit=async event=>{event.preventDefault();try{await saveCurriculumVersion(state.user.uid,Object.fromEntries(new FormData(event.currentTarget)));close();toast(txt('updated'));renderLibrary();}catch(error){err(error);}};}


async function renderLibraryVersion(versionId){const version=state.curriculum.find(item=>item.id===versionId);if(!version){state.libraryVersion=null;renderLibrary();return;}const bn=state.language==='bn';root.innerHTML=empty(bn?'বই লোড হচ্ছে…':'Loading books…','');try{const [books,templates]=await Promise.all([listCurriculumBooks(versionId),listAssessmentTemplates(state.roles.isAdmin?'':state.user.uid)]);state.libraryBooks=books;const canManage=state.roles.isAdmin;const statusLabel=txt(version.status||'draft');const versionActions=canManage?`<button class="btn btn-secondary" data-action="new-book" data-version="${esc(versionId)}">＋ ${bn?'বই যোগ করুন':'Add book'}</button><button class="btn btn-secondary" data-action="new-assessment-template">＋ ${bn?'মূল্যায়ন টেমপ্লেট':'Assessment template'}</button>${version.status!=='published'?`<button class="btn btn-primary" data-action="publish-version" data-id="${esc(versionId)}">${bn?'প্রকাশ করুন':'Publish'}</button>`:''}${version.status!=='archived'?`<button class="btn btn-ghost" data-action="archive-version" data-id="${esc(versionId)}">${bn?'আর্কাইভ করুন':'Archive'}</button>`:''}`:'';root.innerHTML=`<section class="page-heading"><div><button class="text-button" data-action="close-library-version">← ${bn?'সংস্করণ তালিকায় ফিরুন':'Back to versions'}</button><p class="eyebrow">${esc(programmeLabel(version.programmeId,state.language))}</p><h2>${esc(version.name||version.academicYear||'')}</h2><p>${esc(version.academicYear||'')} · ${esc(statusLabel)}${version.sourceUrl?` · <a href="${esc(version.sourceUrl)}" target="_blank" rel="noopener">${bn?'উৎস':'Source'}</a>`:''}</p></div><div class="heading-actions">${versionActions}</div></section><section class="dashboard-grid"><article class="card">${cardHeading(bn?'বই ও অধ্যায়':'Books and chapters',`${books.length} ${bn?'টি বই':'books'}`)}${books.length?`<div class="library-book-list">${books.map(book=>`<article class="library-book"><div><strong>${esc(book.subject||book.title)}</strong><p>${esc(book.classLabel||'')} · ${esc(book.title||'')} · ${Number(book.chapterCount||0)} ${bn?'অধ্যায়':'chapters'}</p></div><div class="row-actions"><button class="btn btn-ghost" data-action="book-chapters" data-version="${esc(versionId)}" data-book="${esc(book.id)}">${bn?'অধ্যায়':'Chapters'}</button>${canManage?`<button class="btn btn-secondary" data-action="new-chapter" data-version="${esc(versionId)}" data-book="${esc(book.id)}">＋</button>`:''}</div></article>`).join('')}</div>`:empty(txt('noData'),bn?'এই সংস্করণে এখনো কোনো বই নেই।':'No books have been added to this version yet.')}</article><article class="card">${cardHeading(bn?'মূল্যায়ন টেমপ্লেট':'Assessment templates',bn?'পুনঃব্যবহারযোগ্য পরীক্ষার কাঠামো':'Reusable exam structures')}${templates.length?`<div class="library-book-list">${templates.slice(0,8).map(template=>`<article class="library-book"><div><strong>${esc(template.name)}</strong><p>${esc(template.classLabel||'')} · ${(template.sections||[]).length} ${bn?'টি অংশ':'sections'}</p></div></article>`).join('')}</div>`:empty(txt('noData'),bn?'প্রথম টেমপ্লেট তৈরি করুন; শিক্ষক পরে এটি নিজের মতো বদলাতে পারবেন।':'Create the first template; teachers can later adapt it to their own assessment.')}</article></section>`;}catch(error){err(error);}}
function bookModal(versionId){const bn=state.language==='bn';open(frame(bn?'বই যোগ করুন':'Add book',bn?'একটি বই ও তার প্রাথমিক অধ্যায় যোগ করুন। নতুন সংস্করণ প্রকাশ করলে পুরোনো বই স্বয়ংক্রিয়ভাবে বদলাবে না।':'Add a book and its first chapters. Publishing a new version never overwrites an older book.',`<form id="bookForm"><div class="form-grid">${input(bn?'শ্রেণি':'Class','classLabel','','required')}${input(bn?'বিষয়':'Subject','subject','','required')}${input(bn?'বইয়ের নাম':'Book title','title','','required')}${input(bn?'ক্রম':'Order','order','1','type="number" min="0"')}${area(bn?'অধ্যায়সমূহ (প্রতি লাইনে একটি)':'Chapters (one per line)','chapters','','placeholder="Chapter 1\nChapter 2"')}</div>${actions()}</form>`));$('#bookForm').onsubmit=async event=>{event.preventDefault();const form=new FormData(event.currentTarget);try{await saveCurriculumBook(state.user.uid,versionId,{classLabel:form.get('classLabel'),subject:form.get('subject'),title:form.get('title'),order:form.get('order'),chapters:String(form.get('chapters')||'').split('\n').map(title=>({title}))});close();toast(txt('updated'));renderLibraryVersion(versionId);}catch(error){err(error);}};}
async function bookChaptersModal(versionId,bookId){const book=(state.libraryBooks||[]).find(item=>item.id===bookId);const bn=state.language==='bn';open(frame(book?.title||book?.subject||'Book',bn?'অধ্যায় লোড হচ্ছে…':'Loading chapters…','<div class="loading-inline">…</div>'));try{const chapters=await listCurriculumChapters(versionId,bookId);$('#modalBody').innerHTML=frame(book?.title||book?.subject||'Book',bn?'অধ্যায়গুলোর তালিকা':'Chapter list',`<div class="chapter-list">${chapters.length?chapters.map(chapter=>`<div class="chapter-row"><span>${num(chapter.order||0)}</span><div><strong>${esc(chapter.title)}</strong>${chapter.objective?`<small>${esc(chapter.objective)}</small>`:''}</div></div>`).join(''):empty(txt('noData'),bn?'এখনো কোনো অধ্যায় নেই।':'No chapters yet.')}</div><div class="modal-actions">${state.roles.isAdmin?`<button class="btn btn-primary" data-action="new-chapter" data-version="${esc(versionId)}" data-book="${esc(bookId)}">＋ ${bn?'অধ্যায় যোগ করুন':'Add chapter'}</button>`:''}<button class="btn btn-ghost" type="button" data-close>${txt('close')}</button></div>`);}catch(error){err(error);close();}}
function chapterModal(versionId,bookId){const bn=state.language==='bn';open(frame(bn?'অধ্যায় যোগ করুন':'Add chapter',bn?'শিক্ষক এই অধ্যায়ের নিজস্ব কাজ পরে সম্পাদনা করতে পারবেন।':'Teachers can later add their own tasks to this chapter.',`<form id="chapterForm"><div class="form-grid">${input(bn?'অধ্যায়ের নাম':'Chapter title','title','','required')}${input(bn?'ক্রম':'Order','order','1','type="number" min="0"')}${area(bn?'উদ্দেশ্য':'Learning objective','objective')}${area(bn?'প্রস্তাবিত কাজ (প্রতি লাইনে একটি)':'Suggested tasks (one per line)','suggestedTasks')}</div>${actions()}</form>`));$('#chapterForm').onsubmit=async event=>{event.preventDefault();const form=new FormData(event.currentTarget);try{await saveCurriculumChapter(state.user.uid,versionId,bookId,{title:form.get('title'),order:form.get('order'),objective:form.get('objective'),suggestedTasks:String(form.get('suggestedTasks')||'').split('\n')});close();toast(txt('updated'));renderLibraryVersion(versionId);}catch(error){err(error);}};}
function assessmentTemplateModal(){const bn=state.language==='bn';open(frame(bn?'মূল্যায়ন টেমপ্লেট যোগ করুন':'Add assessment template',bn?'এটি একটি কাঠামো; শিক্ষক পরীক্ষার সময় নাম, বিষয়, পূর্ণমান ও অংশ বদলাতে পারবেন।':'This is a structure; a teacher can change title, subjects, marks, and sections when creating an assessment.',`<form id="assessmentTemplateForm"><div class="form-grid">${input(bn?'টেমপ্লেটের নাম':'Template name','name','','required')}${input(bn?'শ্রেণি (ঐচ্ছিক)':'Class (optional)','classLabel')}${select(txt('programme'),'programmeId',PROGRAMMES.map(item=>({value:item.id,label:item[state.language]})))}${area(bn?'অংশ ও পূর্ণমান (যেমন: লিখিত | 70)':'Sections and marks (e.g. Written | 70)','sections','','placeholder="Written | 70\nMCQ | 30"')}</div>${actions()}</form>`));$('#assessmentTemplateForm').onsubmit=async event=>{event.preventDefault();const form=new FormData(event.currentTarget);const sections=String(form.get('sections')||'').split('\n').map(line=>{const [name,fullMarks]=line.split('|');return{name,fullMarks};});try{await saveAssessmentTemplate(state.user.uid,{name:form.get('name'),classLabel:form.get('classLabel'),programmeId:form.get('programmeId'),scope:state.roles.isAdmin?'global':'teacher',status:'published',sections});close();toast(txt('updated'));renderLibraryVersion(state.libraryVersion);}catch(error){err(error);}};}
async function updateVersionStatus(versionId,status){try{await setCurriculumVersionStatus(state.user.uid,versionId,status);toast(txt('updated'));state.curriculum=await listCurriculumVersions(state.roles.isAdmin);renderLibraryVersion(versionId);}catch(error){err(error);}}

async function copyText(value){const text=String(value||'');try{if(navigator.clipboard?.writeText){await navigator.clipboard.writeText(text);}else{const area=document.createElement('textarea');area.value=text;area.style.position='fixed';area.style.opacity='0';document.body.append(area);area.select();document.execCommand('copy');area.remove();}toast(txt('codeCopied'));}catch(error){console.warn('Clipboard unavailable',error);toast(`${txt('roomCode')}: ${text}`);}}
async function shareRoomCode(code,name){const text=`${name||'Batch'} · ${txt('roomCode')}: ${code}`;try{if(navigator.share){await navigator.share({title:name||txt('roomCode'),text});}else await copyText(text);}catch(error){if(error?.name!=='AbortError')await copyText(text);}}
async function studentRoom(id){const student=state.students.find(s=>s.id===id);if(!student)return;try{const code=await createBatchRoom(state.user.uid,student,state.profile?.name);state.students=state.students.map(item=>item.id===id?{...item,roomCode:code}:item);toast(`${txt('roomCode')}: ${code}`);render();}catch(error){err(error);}}
async function terminateRoom(id){const student=state.students.find(s=>s.id===id);if(!student)return;try{await terminateStudentRoom(state.user.uid,student);state.students=state.students.map(item=>item.id===id?{...item,roomCode:null}:item);toast(state.language==='bn'?'রুম বন্ধ করা হয়েছে।':'Room terminated.');render();}catch(error){err(error);}}
async function batchRoom(id){const batch=state.batches.find(b=>b.id===id);if(!batch)return;try{const code=await ensureBatchRoom(state.user.uid,batch);state.batches=state.batches.map(item=>item.id===id?{...item,roomCode:code}:item);toast(`${txt('roomCode')}: ${code}`);render();}catch(error){err(error);}}
function linkGuardianModal(request){const candidates=state.students.filter(student=>!request.batchId||(student.batchIds||[]).includes(request.batchId));const requested=request.childName?`<div class="privacy-note">${state.language==='bn'?'অভিভাবকের দেওয়া শিশুর নাম':'Guardian-entered child name'}: <strong>${esc(request.childName)}</strong></div>`:'';open(frame(state.language==='bn'?'শিশুকে নির্বাচন করুন':'Choose the child',state.language==='bn'?'সঠিক শিক্ষার্থী নির্বাচন করলেই ব্যক্তিগত রিপোর্টের অনুমতি দেওয়া হবে।':'Choose the correct student before approving the private report.',`${requested}<form id="guardianLinkForm"><label class="field"><span>${state.language==='bn'?'শিক্ষার্থী':'Student'}</span><select name="studentId" required>${candidates.map(student=>`<option value="${esc(student.id)}">${esc(student.name)}${student.grade?` · ${esc(student.grade)}`:''}</option>`).join('')}</select></label>${actions()}</form>`));$('#guardianLinkForm').onsubmit=async event=>{event.preventDefault();try{const studentId=new FormData(event.currentTarget).get('studentId');const student=state.students.find(item=>item.id===studentId);await approveGuardianRequest(state.user.uid,request,studentId,student?.name||'');close();toast(txt('approved'));}catch(error){err(error);}};}
async function approve(id){const request=state.requests.find(x=>x.id===id);if(!request)return;if(!request.studentId){linkGuardianModal(request);return;}try{const student=state.students.find(item=>item.id===request.studentId);await approveGuardianRequest(state.user.uid,request,'',student?.name||'');toast(txt('approved'));}catch(error){err(error);}}
async function reject(id){const request=state.requests.find(x=>x.id===id);if(!request)return;try{await rejectGuardianRequest(state.user.uid,request);toast(txt('updated'));}catch(error){err(error);}}
async function exportData(){try{const result=await exportTeacherData(state.user.uid);const blob=new Blob([JSON.stringify(result,null,2)],{type:'application/json'});const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download=`student-progress-${new Date().toISOString().slice(0,10)}.json`;link.click();URL.revokeObjectURL(link.href);toast(state.language==='bn'?'ডেটা এক্সপোর্ট তৈরি হয়েছে।':'Data export created.');}catch(error){err(error);}}
function closeProfileMenu(){const menu=$('#profileMenu');if(menu)menu.classList.add('hidden');}
function openSettingsAccount(){closeProfileMenu();toast(state.language==='bn'?'সেটিংস ও অ্যাকাউন্ট অপশন শিগগিরই যোগ হবে।':'Settings and account options will be added soon.');}

function renderGuardian(){show('guardianScreen');refreshGuardianNotifications();const card=$('#guardianCard');if(!state.user)return;if(state.guardianState?.status==='pending'){card.innerHTML=`<span class="eyebrow">${txt('requestSent')}</span><h1>${txt('waitingApproval')}</h1><p>${state.language==='bn'?'শিক্ষক অনুমোদন দিলে আবার প্রবেশ করে রিপোর্ট দেখুন।':'Return here after the teacher approves to view the report.'}</p><button class="btn btn-primary btn-wide" data-guardian="check">${state.language==='bn'?'অনুমতি আবার দেখুন':'Check access again'}</button>`;return;}if(state.guardianState?.approvals?.length){card.innerHTML=`<span class="eyebrow">${txt('guardianChildReport')}</span><h1>${state.language==='bn'?'শিশুর রিপোর্ট নির্বাচন করুন':'Choose a child report'}</h1><p>${state.language==='bn'?'আপনার অনুমোদিত প্রতিটি শিশুর তথ্য আলাদা ও ব্যক্তিগত।':'Each approved child report is separate and private.'}</p><div class="student-list">${state.guardianState.approvals.map(approval=>`<button class="student-row" data-guardian-child="${esc(approval.studentId)}"><span class="mini-avatar">◉</span><span class="row-copy"><strong>${esc(approval.studentName||state.language==='bn'?'অনুমোদিত শিক্ষার্থী':'Approved student')}</strong><span>${state.language==='bn'?'রিপোর্ট খুলুন':'Open report'}</span></span></button>`).join('')}</div>`;$$('[data-guardian-child]').forEach(button=>button.onclick=()=>guardianReport(button.dataset.guardianChild));return;}if(state.guardianState?.studentId){guardianReport(state.guardianState.studentId);return;}if(state.guardianState?.batchId){guardianSharedBatch(state.guardianState.batchId);return;}if(state.guardianRoom){const room=state.guardianRoom;const batchFields=room.type==='batch'?`<label class="field"><span>${state.language==='bn'?'শিশুর পূর্ণ নাম (ব্যক্তিগত রিপোর্টের জন্য)':'Child full name (for private report)'}</span><input id="guardianChildName" placeholder="${state.language==='bn'?'যেমন: আয়াত রহমান':'For example: Ayat Rahman'}"></label>`:'';const immediate=room.type==='batch'&&room.accessMode===RoomAccessMode.IMMEDIATE;card.innerHTML=`<div class="guardian-confirm"><span class="eyebrow">${txt('guardianRoomConfirm')}</span><h1>${esc(room.roomName)}</h1><p>${txt('guardianRoomText')}</p><div class="room-preview"><small>${state.language==='bn'?'শিক্ষক':'Teacher'}</small><strong>${esc(room.teacherName||'Teacher')}</strong><p>${esc(room.description||(state.language==='bn'?'কোনো সংক্ষিপ্ত বর্ণনা নেই।':'No short description.'))}</p></div><div class="privacy-note">${immediate?txt('immediateAccessHelp'):(state.language==='bn'?'এখনও কোনো শিশুর ব্যক্তিগত তথ্য দেখানো হচ্ছে না। অনুরোধ পাঠালে শিক্ষক আপনার Google পরিচয়সহ তা দেখবেন।':'No child-private information is shown yet. The teacher receives your request with your Google identity.')}</div>${batchFields}<div class="modal-actions"><button class="btn btn-ghost" data-guardian="cancel">${txt('cancel')}</button>${immediate?`<button class="btn btn-secondary" data-guardian="continue-shared">${state.language==='bn'?'সাধারণ ব্যাচ রুমে যান':'Open shared batch room'}</button><button class="btn btn-primary" data-guardian="request-child">${state.language==='bn'?'শিশুর রিপোর্টের অনুমতি চান':'Request child report'}</button>`:`<button class="btn btn-primary" data-guardian="request">${txt('requestPermission')}</button>`}</div></div>`;return;}card.innerHTML=`<span class="eyebrow">${txt('guardianAccess')}</span><h1>${txt('guardianAccessTitle')}</h1><p>${txt('guardianAccessText')}</p><form id="guardianLookup"><label class="field"><span>${txt('enterRoomCode')}</span><input name="code" placeholder="${esc(txt('roomCodeHint'))}" required></label><button class="btn btn-primary btn-wide">${txt('continue')}</button></form><div class="privacy-note">${state.language==='bn'?`সাইন ইন: ${esc(state.user.email||'')}`:`Signed in: ${esc(state.user.email||'')}`}</div>`;$('#guardianLookup').onsubmit=async event=>{event.preventDefault();try{const room=await lookupRoom(new FormData(event.currentTarget).get('code'));if(!room)throw new Error(state.language==='bn'?'রুম কোডটি পাওয়া যায়নি।':'Room code was not found.');state.guardianRoom=room;renderGuardian();}catch(error){err(error);}};}
async function guardianSharedBatch(batchId){const target=$('#guardianScreen');target.innerHTML=`<main class="guardian-report"><div class="guardian-report-header"><div><p class="eyebrow">${txt('guardianSharedRoom')}</p><h1>${state.language==='bn'?'ব্যাচের সাধারণ তথ্য':'Shared batch updates'}</h1></div><button class="btn btn-ghost" id="guardianOut">${txt('signOut')}</button></div><article class="card"><p>${state.language==='bn'?'তথ্য লোড হচ্ছে…':'Loading shared updates…'}</p></article></main>`;try{const report=await guardianBatchReport(state.user.uid,batchId);if(!report)throw new Error(txt('failed'));const sessions=recent(report.sessions||[]).slice(0,8);target.innerHTML=`<main class="guardian-report"><div class="guardian-report-header"><div><p class="eyebrow">${txt('guardianSharedRoom')}</p><h1>${esc(report.batch.name)}</h1><p>${esc(report.batch.grade||'')}</p></div><button class="btn btn-ghost" id="guardianOut">${txt('signOut')}</button></div><section class="dashboard-grid"><article class="card">${cardHeading(state.language==='bn'?'ক্লাস আপডেট':'Class updates',esc(report.batch.description||''))}${sessions.length?`<div class="log-list">${sessions.map(session=>`<article class="log-card"><div class="log-top"><strong>${esc((session.subjects||[]).join(', ')||'Class update')} · ${esc(session.topics||'')}</strong><small>${date(session.date||session.createdAt)}</small></div><p>${esc(session.homework||session.notice||'')}</p></article>`).join('')}</div>`:empty(txt('noData'),state.language==='bn'?'এখনও কোনো ক্লাস আপডেট নেই।':'No class update yet.')}</article><article class="card">${cardHeading(state.language==='bn'?'শিশুর ব্যক্তিগত রিপোর্ট':'Child private report',state.language==='bn'?'শুধু শিক্ষক অনুমোদন দিলে দেখা যাবে।':'Visible only after teacher approval.')}<label class="field"><span>${state.language==='bn'?'শিশুর পূর্ণ নাম':'Child full name'}</span><input id="sharedGuardianChildName" placeholder="${state.language==='bn'?'যেমন: আয়াত রহমান':'For example: Ayat Rahman'}"></label><button class="btn btn-primary btn-wide" data-guardian="shared-child">${state.language==='bn'?'অনুমতি চান':'Request permission'}</button></article></section></main>`;$('#guardianOut').onclick=()=>signOutUser();}catch(error){err(error);}}

async function guardianReport(studentId){try{const report=await guardianStudentReport(studentId);if(!report)throw new Error(txt('failed'));await createOrUpdatePresence(studentId,state.user.uid);const logs=recent(report.logs||[]);const assessments=recent(report.assessments||[]);const average=logs.length?Math.round(logs.reduce((sum,x)=>sum+Number(x.learning||0),0)/logs.length*20):0;$('#guardianScreen').innerHTML=`<main class="guardian-report"><div class="guardian-report-header"><div><p class="eyebrow">${txt('guardianChildReport')}</p><h1>${esc(report.student.name)}</h1><p>${esc(report.student.grade||'')}</p></div><button class="btn btn-ghost" id="guardianOut">${txt('signOut')}</button></div><div class="guardian-grid">${metric('↗',txt('learningProgress'),`${average}%`,state.language==='bn'?'দৈনিক নথির গড়':'Daily average')}${metric('✓',txt('checklist'),'—',state.language==='bn'?'রোডম্যাপ':'Roadmap','teal')}${metric('★',txt('latestAssessment'),assessments[0]?`${Math.round(assessments[0].percentage||0)}%`:'—',assessments[0]?.title||txt('noData'),'orange')}</div><section class="dashboard-grid"><article class="card">${cardHeading(txt('learningJourney'),state.language==='bn'?'সাম্প্রতিক শেখা':'Recent learning')}${logs.length?`<div class="log-list">${logs.slice(0,6).map(x=>`<article class="log-card"><div class="log-top"><strong>${esc(x.subject)} · ${esc(x.topic)}</strong><small>${date(x.logDate||x.createdAt)}</small></div><p>${esc(x.homework||x.note||'')}</p></article>`).join('')}</div>`:empty(txt('noData'),txt('noData'))}</article><article class="card">${cardHeading(txt('parentGuidance'),state.language==='bn'?'শিক্ষকের পরামর্শ':'Teacher guidance')}<div class="privacy-note">${esc(report.plan?.weeklyReflection?.parentGuidance||'—')}</div></article></section></main>`;$('#guardianOut').onclick=()=>signOutUser();}catch(error){err(error);}}
async function guardianAction(action){if(action==='cancel'){state.guardianRoom=null;renderGuardian();return;}if(action==='continue-shared'){try{state.guardianState=await createGuardianRequest(state.user,state.guardianRoom);state.guardianRoom=null;renderGuardian();}catch(error){err(error);}return;}if(action==='request'||action==='request-child'){try{const childName=$('#guardianChildName')?.value||'';state.guardianState=await createGuardianRequest(state.user,state.guardianRoom,childName);state.guardianRoom=null;renderGuardian();}catch(error){err(error);}return;}if(action==='shared-child'){try{const childName=$('#sharedGuardianChildName')?.value||'';state.guardianState=await requestGuardianChildLink(state.user,state.guardianState.batchId,childName);renderGuardian();}catch(error){err(error);}return;}if(action==='check'){try{const approvals=await guardianApprovals(state.user.uid);if(approvals.length===1)state.guardianState={studentId:approvals[0].studentId};else if(approvals.length>1)state.guardianState={approvals};else{const batches=await guardianBatchAccess(state.user.uid);if(batches[0])state.guardianState={batchId:batches[0].batchId};else state.guardianState=null;}renderGuardian();}catch(error){err(error);}}}
function openStudentWorkspace(studentId){
  const student=state.students.find(item=>item.id===studentId)||{};
  const url=new URL('https://robiul20202090.github.io/Student-progress/');
  url.searchParams.set('student',studentId);
  url.searchParams.set('embed','1');
  url.searchParams.set('name',student.name||'');
  url.searchParams.set('grade',student.grade||'');
  url.searchParams.set('school',student.schoolName||student.school||'');
  url.searchParams.set('back',location.href);
  window.location.href=url.href;
}
function events(){document.addEventListener('click',event=>{const profileMenu=$('#profileMenu');if(profileMenu&&!profileMenu.classList.contains('hidden')&&!event.target.closest('#profileMenu,#profileBtn'))closeProfileMenu();const button=event.target.closest('button,[data-action],[data-view],[data-guardian]');if(!button)return;if(button.dataset.language){setLang(button.dataset.language);return;}if(button.id==='googleSignInBtn'){login('teacher');return;}if(button.id==='guestModeBtn'){startGuestMode();return;}if(button.id==='openGuardianBtn'){state.intent='guardian';if(state.user){show('guardianScreen');renderGuardian();}else login('guardian');return;}if(button.id==='guardianBackBtn'){state.intent='teacher';if(state.user){show('teacherShell');setupTeacher();}else show('signInScreen');return;}if(button.id==='languageBtn'){setLang(state.language==='bn'?'en':'bn');return;}if(button.id==='quickAddBtn'||button.id==='mobileAddBtn'){quickAddModal();return;}if(button.id==='guardianNoticeBtn'){openGuardianNotifications();return;}if(button.id==='menuBtn'){$('#sidebar').classList.toggle('open');return;}if(button.id==='profileBtn'){const menu=$('#profileMenu');menu.classList.toggle('hidden');button.setAttribute('aria-expanded',String(!menu.classList.contains('hidden')));return;}if(button.id==='signOutBtn'){closeProfileMenu();signOutUser();return;}if(button.id==='exportBtn'||button.dataset.action==='menu-backup'){closeProfileMenu();exportData();return;}if(button.id==='settingsBtn'||button.dataset.action==='menu-settings'){openSettingsAccount();return;}if(button.dataset.close!==undefined){close();return;}if(button.dataset.view){setView(button.dataset.view);return;}if(button.dataset.guardian){guardianAction(button.dataset.guardian);return;}switch(button.dataset.action){case'continue-offline-risk':close();localStorage.setItem('spt-guest-mode-v1','1');location.reload();break;case'new-student':studentModal();break;case'new-batch':batchModal();break;case'new-task':taskModal();break;case'new-task-student':taskModal('student');break;case'new-task-batch':taskModal('batch');break;case'toggle-task':{const task=state.tasks.find(item=>item.id===button.dataset.id);if(task)updateTeacherTask(state.user.uid,task.id,{status:task.status==='done'?'due':'done'}).catch(err);break;}case'task-target':{const targetId=button.dataset.targetId;if(button.dataset.targetType==='batch'){state.selectedBatch=targetId;state.selectedStudent=null;}else{state.selectedStudent=targetId;state.selectedBatch=null;}render();break;}case'quick-log':logModal(button.dataset.id);break;case'open-student':openStudentWorkspace(button.dataset.id);break;case'open-batch':state.selectedBatch=button.dataset.id;render();break;case'back-students':state.selectedStudent=null;renderStudents();break;case'back-workspace':state.selectedStudent=null;if(state.view==='plans')renderPlans();else renderStudents();break;case'back-batches':state.selectedBatch=null;renderBatches();break;case'student-room':studentRoom(button.dataset.id);break;case'terminate-room':terminateRoom(button.dataset.id);break;case'batch-room':batchRoom(button.dataset.id);break;case'copy-room-code':copyText(button.dataset.code);break;case'share-room-code':shareRoomCode(button.dataset.code,button.dataset.name);break;case'record-session':sessionModal(button.dataset.id);break;case'approve':approve(button.dataset.id);break;case'reject':reject(button.dataset.id);break;case'export':exportData();break;case'new-version':versionModal();break;case'manage-version':state.libraryVersion=button.dataset.id;renderLibrary();break;case'close-library-version':state.libraryVersion=null;renderLibrary();break;case'new-book':bookModal(button.dataset.version);break;case'book-chapters':bookChaptersModal(button.dataset.version,button.dataset.book);break;case'new-chapter':chapterModal(button.dataset.version,button.dataset.book);break;case'new-assessment-template':assessmentTemplateModal();break;case'publish-version':updateVersionStatus(button.dataset.id,'published');break;case'archive-version':updateVersionStatus(button.dataset.id,'archived');break;case'admin-block':case'admin-unblock':case'admin-promote':case'admin-demote':manageAdminAccount(button.dataset.action,button.dataset.id);break;}});document.addEventListener('keydown',event=>{if(event.key==='Escape'){closeProfileMenu();$('#sidebar')?.classList.remove('open');}});modal.addEventListener('click',event=>{if(event.target===modal)close();});}
events();syncLanguage();state.authTimer=setTimeout(()=>{if(!state.user&&!$('#loadingScreen').classList.contains('hidden')){show('signInScreen');syncLanguage();}},4500);subscribeAuth(authChanged);if('serviceWorker' in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(console.warn));
